<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Group/cat_field',array('cat_id'=>$now_category['cat_id']))}" class="on">字段列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Group/cat_field_add',array('cat_id'=>$now_category['cat_id']))}','添加字段',480,360,true,false,false,addbtn,'add',true);">添加字段</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<!--col/-->							<col/>							<col/>							<col/>							<!--col/-->							<!--col width="180" align="center"/-->						</colgroup>						<thead>							<tr>								<!--th>排序</th-->								<th>名称</th>								<th>短标记(url)</th>                                <th>类型</th>                                <th>是否前端显示</th>								<!--th>状态</th-->								<!--th class="textcenter">操作</th-->							</tr>						</thead>						<tbody>							<if condition="is_array($now_category['cat_field'])">								<volist name="now_category['cat_field']" id="vo">									<tr>										<!--td>{pigcms{$vo.sort}</td-->										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.url}</td>										<td><if condition="$vo['type'] eq 1">多选<else/>单选</if></td>										<!--td><if condition="$vo['status'] eq 1"><font color="green">显示</font><else/><font color="red">隐藏</font></if></td-->										<!--td class="textcenter"><a href="javascript:void(0);" class="delete_row" parameter="cat_id={pigcms{$vo.cat_id}" url="{pigcms{:U('Group/cat_del')}">删除</a></td-->                                        <td>                                            <span class="cb-enable"><label class="cb-enable <if condition="$vo['is_show'] eq 1">selected</if>"><span  onclick="showWitch('{pigcms{$now_category['cat_id']}', '{pigcms{$vo.name}', 1)" >显示</span><input type="radio" value="0" <if condition="$vo['is_show'] eq 1">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['is_show'] eq 0">selected</if>"><span  onclick="showWitch('{pigcms{$now_category['cat_id']}', '{pigcms{$vo.name}', 0)">隐藏</span><input type="radio" value="1" <if condition="$vo['is_show'] eq 0">checked="checked"</if> /></label></span>                                        </td>                                    </tr>								</volist>							<else/>								<tr><td class="textcenter red" colspan="5">商品属性字段 列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script>    var lockInfo = false;    function showWitch(cat_id, name, status) {        if (lockInfo) return;        lockInfo = true;        console.log('切换信息', cat_id, name, status)        var chat_switch_url = "{pigcms{:U('Group/cat_field_show')}";        $.post(chat_switch_url,{'cat_id': cat_id, 'name': name, 'is_show': status},function(data){            console.log('返回值----------', data);            if (data && (data.status === 1 || data.status === '1')) {                location.reload();            }            lockInfo = false;        },'json');    }</script><include file="Public:footer"/>